def is_good(m, memo=None):
    if memo is None:
        memo = {}
    if m in memo:
        return memo[m]

    s_m = str(m)
    # Distinct nonzero digits
    if any(d == '0' for d in s_m) or len(set(s_m)) != len(s_m):
        memo[m] = False
        return False

    # Single-digit number
    if len(s_m) == 1:
        memo[m] = True
        return True

    # Try removing one digit
    for i in range(len(s_m)):
        # Remove digit at index i
        m_prime_str = s_m[:i] + s_m[i+1:]
        m_prime = int(m_prime_str)

        if m_prime != 0 and m % m_prime == 0:
            if is_good(m_prime, memo):
                memo[m] = True
                return True

    memo[m] = False
    return False

