def find_largest_good():
    good_by_length = {1: set(range(1, 10))}

    for length in range(2, 10):
        current_good = set()
        for m_prime in good_by_length[length - 1]:
            s_prime = str(m_prime)
            for d in range(1, 10):
                d_str = str(d)
                if d_str in s_prime:
                    continue
                for i in range(len(s_prime) + 1):
                    m_str = s_prime[:i] + d_str + s_prime[i:]
                    m = int(m_str)
                    if m % m_prime == 0:
                        current_good.add(m)
        if not current_good:
            break
        good_by_length[length] = current_good

    all_good = set()
    for length in good_by_length:
        all_good.update(good_by_length[length])
    return max(all_good)

print(find_largest_good())

